-- Rega24 production data (D1 rega24-migration): four more Rega24Travel sub-categories, 2026-11-18 (full travel scope).
-- Tour operators, chauffeur services, shuttle services, intercity & international transport. Same rows as
-- src/config/travel.ts (TRAVEL_SUBCATEGORIES, positions 10-13) and prisma/seed.ts (checked by tests/travel.test.ts).
-- ADDITIVE ONLY, same rules as 20261118_travel_subcategories.sql: inserts only when key and slug are unused and the
-- parent exists; never updates or deletes; running it again changes nothing. Pre-check on production: slugs unused.
-- Undo: DELETE FROM Category WHERE id IN ('seed_category_travel_tour-operators','seed_category_travel_chauffeur-services','seed_category_travel_shuttle-services','seed_category_travel_intercity-international') AND NOT EXISTS (SELECT 1 FROM Business b WHERE b.categoryId=Category.id) AND NOT EXISTS (SELECT 1 FROM Service s WHERE s.categoryId=Category.id);
-- Apply: node scripts/project-identity-guard.mjs --project REGA && npx wrangler d1 execute rega24-migration --remote --file prisma/d1/data/20261118b_travel_scope_subcategories.sql
WITH v(k,parent,ckb,kmr,de,en,ar,fa,tr,ord) AS (VALUES ('tour-operators','travel-tickets','ڕێکخەرانی گەشت و تووری گەشتیاری','Organîzatorên turan','Reiseveranstalter','Tour Operators','منظمو الرحلات السياحية','برگزارکنندگان تور','Tur Operatörleri',10),('chauffeur-services','transport-moving','خزمەتگوزاری شۆفێری تایبەت','Xizmetên şofêrê taybet','Chauffeurservice','Chauffeur Services','خدمات السائق الخاص','خدمات راننده اختصاصی','Şoför Hizmetleri',11),('shuttle-services','transport-moving','خزمەتگوزاری شاتڵ','Xizmetên şatilê','Shuttle-Service','Shuttle Services','خدمات النقل المكوكي','خدمات شاتل','Servis ve Shuttle Hizmetleri',12),('intercity-international','transport-moving','گواستنەوەی نێوان شارەکان و نێودەوڵەتی','Veguhastina navbajarî û navneteweyî','Fernverkehr & internationale Transporte','Intercity & International Transport','النقل بين المدن والنقل الدولي','حمل‌ونقل بین‌شهری و بین‌المللی','Şehirlerarası ve Uluslararası Taşımacılık',13)) INSERT INTO Category (id,key,slug,parentId,nameCkb,nameKmr,nameDe,nameEn,nameAr,nameFa,nameTr,icon,sectionKey,sortOrder,isActive,createdAt,updatedAt) SELECT 'seed_category_travel_'||k,k,k,(SELECT id FROM Category WHERE key=v.parent),ckb,kmr,de,en,ar,fa,tr,'near','businesses',ord,1,1795030800000,1795030800000 FROM v WHERE NOT EXISTS (SELECT 1 FROM Category c WHERE c.key=v.k OR c.slug=v.k) AND EXISTS (SELECT 1 FROM Category WHERE key=v.parent);
